func _unhandled_input(event: InputEvent) -> void:
	if dead or not controls_enabled or get_tree().paused:
		return
	if event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		var s := MOUSE_SCALE * GameState.sensitivity
		_look(-event.relative.x * s, -event.relative.y * s * (-1.0 if GameState.invert_y else 1.0))
	elif event.is_action_pressed("jump"):
		_jump_queued = true
	elif event.is_action_pressed("interact"):
		try_interaction()
	elif event.is_action_pressed("pickup"):
		try_pickup()
	elif event.is_action_pressed("switch_dimension"):
		begin_switch()

func switch_target(pos: Vector3) -> Vector3:
	var other := "b" if current_dim == "a" else "a"
	if not dims.has(other):
		return Vector3.INF
	var cell := world_to_cell(pos)
	if not walkable(other, cell) and not _platform_under(other, pos):
		return Vector3.INF
	var target := pos + Vector3(0, DIM_Y[other] - DIM_Y[current_dim], 0)
	var params := PhysicsShapeQueryParameters3D.new()
	var capsule := CapsuleShape3D.new()
	capsule.radius = 0.34
	capsule.height = 1.7
	params.shape = capsule
	params.transform = Transform3D(Basis.IDENTITY, target + Vector3(0, 0.95, 0))
	params.collision_mask = 1
	var exclude: Array[RID] = [player.get_rid()]
	if player.held:
		exclude.append(player.held.get_rid())
	params.exclude = exclude
	if not get_world_3d().direct_space_state.intersect_shape(params, 1).is_empty():
		return Vector3.INF
	return target

func _on_placed(item: Pickable) -> void:
	if discharge and item.is_empty():
		return
	if not discharge and item.is_full():
		return
	working = true
	_hum.play()

func _process(delta: float) -> void:
	_t += delta
	if working and held:
		var value := held.energy + (-rate if discharge else rate) * delta
		held.set_energy(value)
		if (discharge and held.is_empty()) or (not discharge and held.is_full()):
			working = false
			_hum.stop()
			Audio.play_at("charged", global_position, self)
			emit_event("discharged" if discharge else "charged")

func _on_body_entered(body: Node) -> void:
	if body is Pickable and (body.kind == "cell" and not body.is_empty() or body.kind == "core"):
		var item: Pickable = body
		var start := global_position + Vector3(0, 2.2, 0)
		var away := item.global_position - global_position
		away.y = 0
		# Throw it back the way it came.
		var local := global_basis.inverse() * away
		var normal := global_basis.z * (1.0 if local.z >= 0.0 else -1.0)
		item.drop()
		item.linear_velocity = normal * EJECT_SPEED + Vector3(0, 3.0, 0)
		_show_arc(start, item.global_position)
		Audio.play_at("zap", item.global_position, self)
		if level:
			level.spawn_flash(item.global_position, Color(0.6, 0.85, 1.0))
		emit_event("gate_reject")

if shield_up and shield_generator and key == "a":
	var flat := shield_generator.global_position - target
	flat.y = 0.0
	if flat.length() < STRIKE_RADIUS and absf(shield_generator.global_position.y - target.y) < 4.0:
		_destroy_shield()
var player: Player = level.player
if level.current_dim == key and player.global_position.distance_to(target) < STRIKE_RADIUS:
	await level.get_tree().create_timer(0.15).timeout
	player.die("Struck by the guardian")

func _unhandled_input(event: InputEvent) -> void:
	if completed:
		return
	if event.is_action_pressed("pause"):
		if paused and hud.options_open():
			return
		set_paused(not paused)
		get_viewport().set_input_as_handled()
	elif paused and event is InputEventKey and event.pressed and not event.echo:
		if event.is_action_pressed("restart"):
			GameState.restart_level()
		elif event.is_action_pressed("skip_level"):
			skip_level()
	elif not paused and event is InputEventMouseButton and event.pressed and Input.mouse_mode != Input.MOUSE_MODE_CAPTURED:
		Input.mouse_mode = Input.MOUSE_MODE_CAPTURED
